content:
这篇文章记录我在准备蓝桥杯鸿蒙应用开发赛道时的学习路线与实践总结，重点放在赛题思路、开发节奏与避坑点上，便于后续复盘与持续改进。
ArkTS 基础语法变量、数据类型ArkTS 是强类型语言（变量类型固定）

变量
// 方式1：显式指定类型（推荐，比赛写更规范）let 变量名: 类型 = 初始值;// 方式2：类型推导（简单场景用）let 变量名 = 初始值;// 示例（比赛常用）let userName: string = &quot;蓝桥杯选手&quot;; // 用户名let age: number = 20; // 年龄let isLogin: boolean = false; // 是否登录let scoreList: number[] = [90, 85, 95]; // 分数列表

常量（不可修改，比赛中存固定值）
const 常量名: 类型 = 固定值;// 示例（比赛常用）const BASE_URL: string = &quot;https://api.lanqiao.cn&quot;; // 接口地址const MAX_SCORE: number = 100; // 满分

高频数据类型


类型
说明
示例



string
字符串
let title &#x3D; “备忘录”（自动推导类型）


number
数字（整数&#x2F;小数）
let count &#x3D; 10; let price &#x3D; 9.9


boolean
布尔值
let isCheck &#x3D; true


数组[]
列表数据
let list &#x3D; [1,2,3]


对象interface Goods&#123;  title:string  price:number&#125;let vase:Goods = &#123;  title:&quot;汽水&quot;,  price:6.66&#125;console.log(&quot;商品是&quot;,vase.title);console.log(&quot;价格是&quot;,vase.price);

字符类常用操作// 拼接（拼接用户输入/接口数据）let name = &quot;张三&quot;;let info = `姓名：$&#123;name&#125;，年龄：$&#123;20&#125;`; // 推荐用模板字符串// 长度（判断输入是否为空）let input = &quot;&quot;;if (input.length === 0) &#123;  console.log(&quot;输入不能为空&quot;); // 比赛中表单验证必用&#125;// 截取（处理长文本）let str = &quot;蓝桥杯鸿蒙赛&quot;;let shortStr = str.substring(0, 3); // 结果：蓝桥杯// 分开(处理长文本)let strArray = str.split(&#x27;,&#x27;);console.log(&quot;分割后的数组：&quot;, strArray); // 输出：[&quot;蓝桥杯&quot;, &quot;鸿蒙赛&quot;]console.log(&quot;原始字符串：&quot;, str); // 输出：蓝桥杯,鸿蒙赛

数组常用操作let scoreList: number[] = [80, 85, 90];// 新增元素（添加成绩）scoreList.push(95); // 结果：[80,85,90,95]// 删除最后一个元素scoreList.pop(); // 结果：[80,85,90]// 遍历数组（展示列表）for (let score of scoreList) &#123;  console.log(&quot;分数：&quot;, score);&#125;// 按索引取值let firstScore = scoreList[0]; // 80

类型转换ArkTS 不会自动转换类型，以下场景必用：
字符串 ↔ 数字（表单 &#x2F; 接口数据处理）// 字符串转数字（输入框输入的是字符串，计算需转数字）let inputStr = &quot;99&quot;;let inputNum = Number(inputStr); // 99let sum = inputNum + 1; // 100// 数字转字符串（展示到页面）let num = 100;let showText = &quot;得分：&quot; + num.toString(); // &quot;得分：100&quot;

布尔值判断（状态控制）// 空字符串、0、undefined 转布尔值都是 falselet input = &quot;&quot;;if (Boolean(input)) &#123;  console.log(&quot;输入有内容&quot;);&#125; else &#123;  console.log(&quot;输入为空&quot;); // 执行这里&#125;

测试定义学生信息，计算总分并展示
// 1. 定义常量（固定值）const SUBJECTS: string[] = [&quot;语文&quot;, &quot;数学&quot;, &quot;英语&quot;]; // 科目列表// 2. 定义学生对象let student = &#123;  name: &quot;蓝桥杯本科组&quot;,  scores: [85, 92, 88], // 三科成绩  isPass: false // 是否及格（总分≥240及格）&#125;;// 3. 计算总分let totalScore: number = 0;for (let score of student.scores) &#123;  totalScore += score;&#125;// 4. 判断是否及格student.isPass = totalScore &gt;= 240;// 5. 拼接展示文本（页面显示用）let resultText: string = `  姓名：$&#123;student.name&#125;  总分：$&#123;totalScore&#125;  及格状态：$&#123;student.isPass ? &quot;及格&quot; : &quot;不及格&quot;&#125;`;console.log(resultText);

函数ArkTS 函数语法和 TypeScript 高度一致，但结合鸿蒙组件开发有专属规范，先掌握核心定义方式：
基本语法// 完整写法（推荐比赛用，类型明确+代码规范）function 函数名(参数1: 类型, 参数2: 类型): 返回值类型 &#123;  // 函数体  return 返回值;&#125;// 示例：计算总分（比赛常考数据统计）function calculateTotal(scores: number[]): number &#123;  let total = 0;  for (let score of scores) &#123;    total += score;  &#125;  return total;&#125;		

简化写法
// 1. 省略返回值类型（类型推导）function sayHello(name: string) &#123;  return `你好，$&#123;name&#125;`;&#125;// 2. 无参数+无返回值（比赛中按钮点击回调常用）function showToast() &#123;  promptAction.showToast(&#123; message: &quot;操作成功&quot; &#125;);&#125;// 3. 箭头函数（回调场景高频）const add = (a: number, b: number): number =&gt; a + b;		

高频函数类型普通函数// 示例1：分数转等级（比赛常考数据格式化）function scoreToLevel(score: number): string &#123;  if (score &gt;= 90) return &quot;优秀&quot;;  if (score &gt;= 80) return &quot;良好&quot;;  if (score &gt;= 60) return &quot;及格&quot;;  return &quot;不及格&quot;;&#125;

组件内成员函数@Entry@Componentstruct FuncDemo &#123;  @State scores: number[] = [80, 85, 90];  @State total: number = 0;  // 组件成员函数（访问状态变量需加this）  calculateTotal(): void &#123;    this.total = this.scores.reduce((sum, s) =&gt; sum + s, 0);  &#125;  build() &#123;    Column() &#123;      Button(&quot;计算总分&quot;)        .onClick(() =&gt; &#123;          // 调用成员函数          this.calculateTotal();          promptAction.showToast(&#123; message: `总分：$&#123;this.total&#125;` &#125;);        &#125;)    &#125;  &#125;&#125;

回调函数（重点）@Entry@Componentstruct FuncDemo &#123;  @State userName: string = &quot;&quot;;  // 封装输入框变化的回调函数（复用逻辑）  onInputChange(value: string): void &#123;    this.userName = value; // 更新状态变量    console.log(&quot;当前输入：&quot;, this.userName);  &#125;  build() &#123;    Column() &#123;      // 1. 直接写箭头函数（简单场景）      Button(&quot;重置输入&quot;)        .onClick(() =&gt; &#123;          this.userName = &quot;&quot;;        &#125;)      // 2. 调用封装的回调函数（复杂场景推荐）      TextInput(&#123; placeholder: &quot;请输入姓名&quot; &#125;)        .onChange((e) =&gt; this.onInputChange(e.value))        .margin(10)        .width(300);      Text(`你输入的姓名：$&#123;this.userName&#125;`)    &#125;  &#125;&#125;
